-- Generated by tools/build_item_data.py; do not edit.
return {["scripts/items/trident.lua"]={["Path"]="scripts/items/trident.lua",["SHA256"]="84cd3e69f95e672f95aaf23ea7377f0aba96f0bb2ac3b41108d0ac9e701c5335",["Text"]="-----------------------------------\n-- ID: 16837\n-- Item: Trident\n-- Additional effect: lightning damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = 15 + utils.clamp(dStat / 3, 0, 18), -- 15 + 0-18% over 54 dINT, approx.\n        basePower      = math.randomInt(9, 12),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.THUNDER,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/trilobite.lua"]={["Path"]="scripts/items/trilobite.lua",["SHA256"]="f3ae7384040b153e84aa5d5b83c32f695bf991de5017798287552e39333f9a4b",["Text"]="-----------------------------------\n-- ID: 4317\n-- Item: Trilobite\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity -5\n-- Vitality 3\n-- Defense +16%\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, -5)\n    effect:addMod(xi.mod.VIT, 3)\n    effect:addMod(xi.mod.DEFP, 16)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/trizek_ring.lua"]={["Path"]="scripts/items/trizek_ring.lua",["SHA256"]="6f4e1833865786a35fecff5f862dc941316667236de622f8f752a960920cc4d7",["Text"]="-----------------------------------\n-- ID: 27557\n-- Item: trizek ring\n-- Capacity point bonus\n-----------------------------------\n-- Bonus: +150%\n-- Duration: 720 min\n-- Max bonus: 30000 exp\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if target:hasStatusEffect(xi.effect.COMMITMENT) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.COMMITMENT\n    local power     = 150\n    local duration  = 43200\n    local subpower  = 30000\n\n    xi.itemUtils.addItemExpEffect(target, effect, power, duration, subpower)\nend\n\nreturn itemObject\n"},["scripts/items/trollbane.lua"]={["Path"]="scripts/items/trollbane.lua",["SHA256"]="57f3846a8884b6503af71aff05bf8a783efbe998376d6193ffaf08e731658fbd",["Text"]="-----------------------------------\n-- ID: 18694\n-- Item: Trollbane\n-- Item Effect: Enchantment: VIT +10\n-- Duration: 60 Minutes\n-- Only usable in Arrapago Reef, Halvung, or Mamook. Effect lost upon zoning or unequipping.\n-- https://wiki.ffo.jp/html/4400.html\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local zoneId = target:getZoneID()\n\n    if\n        zoneId == xi.zone.ARRAPAGO_REEF or\n        zoneId == xi.zone.HALVUNG or\n        zoneId == xi.zone.MAMOOK\n    then\n        return 0\n    else\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.TROLLBANE) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 3600, origin = user, flag = xi.effectFlag.ON_ZONE, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.TROLLBANE })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.VIT, 10)\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.TROLLBANE)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/troopers_ring.lua"]={["Path"]="scripts/items/troopers_ring.lua",["SHA256"]="4fe6600683e86e35d5396619652cf1a42b41238712359bc0d580a4bfbe6db2bc",["Text"]="-----------------------------------\n-- ID: 15560\n-- Item: Trooper's Ring\n-- Item Effect: Restores 100-115 HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getHP() == target:getMaxHP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local hpHeal = math.randomInt(100, 115)\n    local dif = target:getMaxHP() - target:getHP()\n    if hpHeal > dif then\n        hpHeal = dif\n    end\n\n    target:addHP(hpHeal)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP, 0, hpHeal)\nend\n\nreturn itemObject\n"},["scripts/items/tropical_clam.lua"]={["Path"]="scripts/items/tropical_clam.lua",["SHA256"]="551901dacd3e9a1c4e2670a779c3490c8fa66527f2f887a78d9ca66b66f55d46",["Text"]="-----------------------------------\n-- ID: 5124\n-- Item: Tropical Clam\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Vitality 4\n-- Dexterity -5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.VIT, 4)\n    effect:addMod(xi.mod.DEX, -5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/tropical_crepe.lua"]={["Path"]="scripts/items/tropical_crepe.lua",["SHA256"]="c2f0d6756c30ae4eb021010b57397a7acab972133a8d45994aa2227373ea015f",["Text"]="-----------------------------------\n-- ID: 6567\n-- Item: Tropical Crepe\n-- Food Effect: 30 minutes, all Races\n-----------------------------------\n-- INT +2\n-- MND +2\n-- Magic Accuracy +20% (Max. 90)\n-- \"Magic Def. Bonus\" +1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.INT, 2)\n    effect:addMod(xi.mod.MND, 2)\n    effect:addMod(xi.mod.FOOD_MACCP, 20)\n    effect:addMod(xi.mod.FOOD_MACC_CAP, 90)\n    effect:addMod(xi.mod.MDEF, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/truelove_chocolate.lua"]={["Path"]="scripts/items/truelove_chocolate.lua",["SHA256"]="0fcbd240da18f9016608f6d212438a9927ead9ca98abd5ce515a05bfcd790f6f",["Text"]="-----------------------------------\n-- ID: 5231\n-- Item: truelove_chocolate\n-- Food Effect: 4Hrs, All Races\n-----------------------------------\n-- MP 10\n-- MP Recovered While Healing 4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 10)\n    effect:addMod(xi.mod.MPHEAL, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/trump_card_case.lua"]={["Path"]="scripts/items/trump_card_case.lua",["SHA256"]="cb03f7b215370d7fa65c526ad858fd7b742cc0dd4656c77be32a4023046be572",["Text"]="-----------------------------------\n-- Trump Card Case\n-- Lua By Reefed406\n-- ItemID : 5870\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.TRUMP_CARD, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/trumpet_shell.lua"]={["Path"]="scripts/items/trumpet_shell.lua",["SHA256"]="d66f7f85a2d1b8f272f5dba0f4972fb7380d31824940b039429c1749535a4d8f",["Text"]="-----------------------------------\n-- ID: 5466\n-- Item: Trumpet Shell\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity -5\n-- Vitality 4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, -5)\n    effect:addMod(xi.mod.VIT, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/tsurugitachi.lua"]={["Path"]="scripts/items/tsurugitachi.lua",["SHA256"]="5da5efe37b2bda510d2bcd24ddd485f8c2718316025871baed48628413c5e415",["Text"]="-----------------------------------\n-- ID: 18444\n-- Item: Tsurugitachi\n-- Item Effect: TP +10\n-- Durration: Instant\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:addTP(100)\nend\n\nreturn itemObject\n"},["scripts/items/tube_of_clear_salve_i.lua"]={["Path"]="scripts/items/tube_of_clear_salve_i.lua",["SHA256"]="c38b192210e7b65fd09f306f9908e258454187618447023809235872d9bd7b55",["Text"]="-----------------------------------\n-- ID: 5837\n-- Item: tube_of_clear_salve_i\n-- Item Effect: Instantly removes 1-2 negative status effects at random from pet\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:hasPet() then\n        return xi.msg.basic.REQUIRES_A_PET\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local pet = target:getPet()\n    local effects =\n    {\n        xi.effect.PETRIFICATION,\n        xi.effect.SILENCE,\n        xi.effect.BANE,\n        xi.effect.CURSE_II,\n        xi.effect.CURSE_I,\n        xi.effect.PARALYSIS,\n        xi.effect.PLAGUE,\n        xi.effect.POISON,\n        xi.effect.DISEASE,\n        xi.effect.BLINDNESS\n    }\n\n    local count = math.randomInt(1, 2)\n    local random = 1\n\n    xi.itemUtils.removeMultipleEffects(pet, effects, count, random)\nend\n\nreturn itemObject\n"},["scripts/items/tube_of_clear_salve_ii.lua"]={["Path"]="scripts/items/tube_of_clear_salve_ii.lua",["SHA256"]="532d996fcab2bff8e21d7eb9b33606049f23bda254a2aaacffccdc84d81d40d9",["Text"]="-----------------------------------\n-- ID: 5838\n-- Item: tube_of_clear_salve_ii\n-- Item Effect: Instantly removes all negative status effects from pet\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:hasPet() then\n        return xi.msg.basic.REQUIRES_A_PET\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local pet = target:getPet()\n\n    local effects =\n    {\n        xi.effect.PETRIFICATION,\n        xi.effect.SILENCE,\n        xi.effect.BANE,\n        xi.effect.CURSE_II,\n        xi.effect.CURSE_I,\n        xi.effect.PARALYSIS,\n        xi.effect.PLAGUE,\n        xi.effect.POISON,\n        xi.effect.DISEASE,\n        xi.effect.BLINDNESS\n    }\n\n    local count = 10\n\n    xi.itemUtils.removeMultipleEffects(pet, effects, count)\nend\n\nreturn itemObject\n"},["scripts/items/tube_of_healing_salve_i.lua"]={["Path"]="scripts/items/tube_of_healing_salve_i.lua",["SHA256"]="67832bb86c4d71e7013792d46e3f1303b76916007b656a9a5e74ce821fe04029",["Text"]="-----------------------------------\n-- ID: 5835\n-- Item: tube_of_healing_salve_i\n-- Item Effect: Instantly restores 50% of pet HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:hasPet() then\n        return xi.msg.basic.REQUIRES_A_PET\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local pet = target:getPet()\n    if not pet then\n        return\n    end\n\n    local totalHP = pet:getMaxHP() / 2\n    pet:addHP(totalHP)\n    pet:messageBasic(xi.msg.basic.RECOVERS_HP, 0, totalHP)\nend\n\nreturn itemObject\n"},["scripts/items/tube_of_healing_salve_ii.lua"]={["Path"]="scripts/items/tube_of_healing_salve_ii.lua",["SHA256"]="8f3f9b92ed3cbe0e5c007c203e6dc0b20f97d3c3f335232aefe8727e4acf1382",["Text"]="-----------------------------------\n-- ID: 5836\n-- Item: tube_of_healing_salve_ii\n-- Item Effect: Instantly restores 100% of pet HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:hasPet() then\n        return xi.msg.basic.REQUIRES_A_PET\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local pet = target:getPet()\n    if not pet then\n        return\n    end\n\n    local totalHP = pet:getMaxHP()\n    pet:addHP(totalHP)\n    pet:messageBasic(xi.msg.basic.RECOVERS_HP, 0, totalHP)\nend\n\nreturn itemObject\n"},["scripts/items/tulfaire_quiver.lua"]={["Path"]="scripts/items/tulfaire_quiver.lua",["SHA256"]="c0aad170b74ef9ad6ef18e428a0d85c467d49830cbcff94202bbf740bc59f4d8",["Text"]="-----------------------------------\n-- ID: 6201\n-- Tulfaire Quiver\n-- When used, you will obtain one stack of Tulfaire Arrows\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.TULFAIRE_ARROW, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/turkey_with_rolanberry_sauce.lua"]={["Path"]="scripts/items/turkey_with_rolanberry_sauce.lua",["SHA256"]="63634634af13c9fcb563680433281b238f4658742ad5bab580fb11336b71b844",["Text"]="-----------------------------------\n-- ID: 6576\n-- Item: rolanberry_turkey\n-- Food Effect: 4 Hours, All Races\n-----------------------------------\n-- STR +10\n-- Attack +20% (Max. 120)\n-- Ranged Attack +20% (Max. 120)\n-- \"Counter\" +10\n-- \"Resist Amnesia\" +10\n-- https://www.bg-wiki.com/ffxi/Rol._Turkey\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 10)\n    effect:addMod(xi.mod.FOOD_ATTP, 20)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 120)\n    effect:addMod(xi.mod.FOOD_RATTP, 20)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 120)\n    effect:addMod(xi.mod.COUNTER, 10)\n    effect:addMod(xi.mod.AMNESIARES, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/twicer.lua"]={["Path"]="scripts/items/twicer.lua",["SHA256"]="95e4bae47629f195f8abf6c038720730bac7f0b34469c286458f5a6cdf628c86",["Text"]="-----------------------------------\n-- ID: 18216\n-- Item: twicer\n-- Item Effect: DOUBLE_ATTACK 100%\n-- Duration: 30 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.TWICER) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.TWICER)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.TWICER) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 30, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.TWICER })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DOUBLE_ATTACK, 100)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/twilight_cloak.lua"]={["Path"]="scripts/items/twilight_cloak.lua",["SHA256"]="ab0500f315eb7ad30ee32d9937e98691ad2ee8d369bc1d6410564dba7dbd60b9",["Text"]="-----------------------------------\n-- ID: 11363\n-- Equip: Twilight Cloak\n-- Able to cast \"Impact\"\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\nend\n\nitemObject.onItemEquip = function(target, item)\n    target:addSpell(xi.magic.spell.IMPACT, { silentLog = true, saveToDB = false })\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:delSpell(xi.magic.spell.IMPACT, { saveToDB = false })\nend\n\nreturn itemObject\n"},["scripts/items/twinkle_shower.lua"]={["Path"]="scripts/items/twinkle_shower.lua",["SHA256"]="323a7ce879a398967e3b3294b55d7457abb2fed9149cd2ddcd614531b3629a08",["Text"]="-----------------------------------\n-- ID: 4168\n-- Twinkle Shower\n-- Sparkle effects surround the user\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/two-leaf_mandragora_bud.lua"]={["Path"]="scripts/items/two-leaf_mandragora_bud.lua",["SHA256"]="e9af9778d44d3ae8ac7ff49773d651a054fd5372cd0b1a692c99bc9a0d6bb758",["Text"]="-----------------------------------\n-- ID: 4368\n-- Two-Leaf Mandragora Bud\n--  5 Minutes, food effect, All Races\n-----------------------------------\n-- Agility  +2\n-- Vitality -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 2)\n    effect:addMod(xi.mod.VIT, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/uberkuchen.lua"]={["Path"]="scripts/items/uberkuchen.lua",["SHA256"]="745260cb54f38524d25082b715659ad6fef29023c258a2d317e76f3b5a80486c",["Text"]="-----------------------------------\n-- ID: 5615\n-- Item: uberkuchen\n-- Food Effect: 4Hrs, All Races\n-----------------------------------\n-- HP 10\n-- MP % 3 (cap 15)\n-- Intelligence 3\n-- HP Recovered While Healing 2\n-- MP Recovered While Healing 1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 10)\n    effect:addMod(xi.mod.FOOD_MPP, 3)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 15)\n    effect:addMod(xi.mod.HPHEAL, 2)\n    effect:addMod(xi.mod.MPHEAL, 1)\n    effect:addMod(xi.mod.INT, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/ulbuconut.lua"]={["Path"]="scripts/items/ulbuconut.lua",["SHA256"]="e00ec570ebda0cdf78cf2b89b4e5bc047b97a426ef8c1bb25abe691b08b4241a",["Text"]="-----------------------------------\n-- ID: 5966\n-- Item: Ulbuconut\n-- Food Effect: 5 Min, All Races\n-----------------------------------\n-- Agility -3\n-- Intelligence +1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, -3)\n    effect:addMod(xi.mod.INT, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/ulbukan_lobster.lua"]={["Path"]="scripts/items/ulbukan_lobster.lua",["SHA256"]="c0850b324b4dfa6b71756992ff59edaaf2b7444052d556c88720c2b622ad74fb",["Text"]="-----------------------------------\n-- ID: 5960\n-- Item: Ulbukan Lobster\n-- Food Effect: 5 Min, Mithra only\n-----------------------------------\n-- Dexterity -3\n-- Vitality 1\n-- Defense +9%\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, -3)\n    effect:addMod(xi.mod.VIT, 1)\n    effect:addMod(xi.mod.DEFP, 9)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/ulfhedinn_axe.lua"]={["Path"]="scripts/items/ulfhedinn_axe.lua",["SHA256"]="ff14db2917563eecd2b179533050deea4b8cd7e3590f40156a009a365a55f696",["Text"]="-----------------------------------\n-- ID: 17135\n-- Item: Ulfhedinn Axe\n-- Additional effect: ice damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    if not target:isMob() or target:getFamily() ~= xi.mobFamily.HOUND then\n        return 0, 0, 0\n    end\n\n    local pTable =\n    {\n        chance         = 15,\n        basePower      = math.randomInt(7, 10),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.ICE,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/undecennial_ring.lua"]={["Path"]="scripts/items/undecennial_ring.lua",["SHA256"]="204688b8bbddf73cca22a82891e03abe565425be0c504d20daf3ee1858e65eee",["Text"]="-----------------------------------\n-- ID: 28528\n-- Item: Undecennial Ring\n-- Experience point bonus\n-----------------------------------\n-- Bonus: +100%\n-- Duration: 720 min\n-- Max bonus: 11111 exp\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if target:hasStatusEffect(xi.effect.DEDICATION) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.DEDICATION\n    local power     = 100\n    local duration  = 43200\n    local subpower  = 11111\n\n    xi.itemUtils.addItemExpEffect(target, effect, power, duration, subpower)\nend\n\nreturn itemObject\n"},["scripts/items/undulatus_cell.lua"]={["Path"]="scripts/items/undulatus_cell.lua",["SHA256"]="4e402b68090adfffa80e93c4aa922962dda42ab4ce3c93f9df9509970e2db7b3",["Text"]="-----------------------------------\n-- Undulatus Cell\n-- ID 5371\n-- Unlocks ranged and ammo equipment\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.salvage.onCellItemCheck(target, xi.effect.ENCUMBRANCE_I, 0x000C)\nend\n\nitemObject.onItemUse = function(target)\n    return xi.salvage.onCellItemUse(target, xi.effect.ENCUMBRANCE_I, 0x000C, 6)\nend\n\nreturn itemObject\n"},["scripts/items/uskumru.lua"]={["Path"]="scripts/items/uskumru.lua",["SHA256"]="511a7162ba142ae0f80de76d199238285f46739ec4ceef1cb62ecb4b92556dde",["Text"]="-----------------------------------\n-- ID: 5452\n-- Item: Uskumru\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 3\n-- Mind -5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 3)\n    effect:addMod(xi.mod.MND, -5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/vampiric_claws.lua"]={["Path"]="scripts/items/vampiric_claws.lua",["SHA256"]="c88dccb80417e266397d9033a1f12841a3cb2ff0c4a5ccd968fc4ad4f78210fe",["Text"]="-----------------------------------\n-- ID: 17510\n-- Item: Vampiric Claws\n-- Additional effect: en-drain\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n\n    local pTable =\n    {\n        chance          = 16, -- 16% flat, no scaling on proc rate.\n        basePower       = 8 + utils.clamp(dStat, -3, 16) + utils.clamp(math.floor((dStat - 16) / 2), 0, 16),\n        attackType      = xi.attackType.PHYSICAL,\n        physicalElement = xi.damageType.SLASHING,\n        magicalElement  = xi.element.DARK,\n        canResist       = true,\n        lowestResist    = 0.5,\n        limitUndead     = true,\n        drainHP         = true,\n        overDrain       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/velum_cell.lua"]={["Path"]="scripts/items/velum_cell.lua",["SHA256"]="f5ae8ee541de6b3038a7ae8f07482cdf4aef0391812b84d2276dd25d2d949a8f",["Text"]="-----------------------------------\n-- Velum Cell\n-- ID 5380\n-- Removes INT Down effect\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.salvage.onCellItemCheck(target, xi.effect.DEBILITATION, 0x010)\nend\n\nitemObject.onItemUse = function(target)\n    return xi.salvage.onCellItemUse(target, xi.effect.DEBILITATION, 0x010, 15)\nend\n\nreturn itemObject\n"},["scripts/items/venom_bolt_quiver.lua"]={["Path"]="scripts/items/venom_bolt_quiver.lua",["SHA256"]="fc580047243a5f075ce1689f56ced7acf10431c4e57f11af719b041ab2ea2a96",["Text"]="-----------------------------------\n-- ID: 5338\n-- Venom Bolt Quiver\n-- When used, you will obtain one stack of Venom Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.VENOM_BOLT, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/verboshroom.lua"]={["Path"]="scripts/items/verboshroom.lua",["SHA256"]="703653933227b3832ee40d24ac9e70d645bd0def98b7c0d3c6bd2a858f435a33",["Text"]="-----------------------------------\n-- ID: 5967\n-- Item: Verboshroom\n-- Food Effect: 3 Mins, All Races\n-- Poison 2HP / 3Tic\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 180, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\n    if not target:hasStatusEffect(xi.effect.POISON) then\n        target:addStatusEffect(xi.effect.POISON, { power = 2, duration = 180, origin = user, tick = 3 })\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/vial_of_refresh_musk.lua"]={["Path"]="scripts/items/vial_of_refresh_musk.lua",["SHA256"]="e5854867e2bd9e802dc6cb0ef7cb15a79ccc26e879ecf11624ac7b52979eb4d8",["Text"]="-----------------------------------\n-- ID: 18241\n-- Item: Vial of Refresh Musk\n-- Item Effect: Refresh (3 MP per tick)\n-- Duration: 60 Seconds\n-- https://wiki.ffo.jp/html/10081.html\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.VIAL_OF_REFRESH_MUSK) then\n        local effect = target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.VIAL_OF_REFRESH_MUSK)\n        if effect then\n            effect:resetStartTime()\n            effect:setIcon(xi.effect.REFRESH)\n        else\n            target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 60, icon = xi.effect.REFRESH, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.VIAL_OF_REFRESH_MUSK, flag = xi.effectFlag.NO_LOSS_MESSAGE })\n        end\n\n        target:messageBasic(xi.msg.basic.GAINS_EFFECT_OF_STATUS, xi.effect.REFRESH)\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.REFRESH, 3)\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.VIAL_OF_REFRESH_MUSK)\nend\n\nitemObject.onEffectLose = function(target, effect)\n    target:messageBasic(xi.msg.basic.STATUS_WEARS_OFF, xi.effect.REFRESH)\nend\n\nreturn itemObject\n"},["scripts/items/vial_of_tincture.lua"]={["Path"]="scripts/items/vial_of_tincture.lua",["SHA256"]="f85461fae3245b5e65c5658e654a7ff3c5bd398612b2d4d12d6fbb1bbab4f5a5",["Text"]="-----------------------------------\n-- ID: 4148\n-- Item: Tincture\n-- Item Effect: This potion remedies disease and plague\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    if target:hasStatusEffect(xi.effect.PLAGUE) then\n        target:delStatusEffect(xi.effect.PLAGUE)\n    end\n\n    if target:hasStatusEffect(xi.effect.DISEASE) then\n        target:delStatusEffect(xi.effect.DISEASE)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/viking_herring.lua"]={["Path"]="scripts/items/viking_herring.lua",["SHA256"]="0b9eacac32c80e393edcc2ec3bf1a16fdf911cdb5babf935c235c0b61c2e7acc",["Text"]="-----------------------------------\n-- ID: 5183\n-- Item: viking_herring\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Dexterity 4\n-- Mind -3\n-- Attack % 12 (cap 75)\n-- Ranged ATT % 12 (cap 75)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 4)\n    effect:addMod(xi.mod.MND, -3)\n    effect:addMod(xi.mod.FOOD_ATTP, 12)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 75)\n    effect:addMod(xi.mod.FOOD_RATTP, 12)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 75)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/vile_elixir.lua"]={["Path"]="scripts/items/vile_elixir.lua",["SHA256"]="bfe14bd7b73d1ba4b2cc6f7ab6379b515cddd7c2cc319aa9fe51ec9e1b6dca35",["Text"]="-----------------------------------\n-- ID: 4174\n-- Item: Vile Elixir\n-- Item Effect: Instantly restores 25% of HP and MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    local mHP = target:getMaxHP()\n    local cHP = target:getHP()\n    local mMP = target:getMaxMP()\n    local cMP = target:getMP()\n\n    if mHP == cHP and mMP == cMP then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE -- Does not let player use item if their hp and mp are full\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target)\n    target:addHP((target:getMaxHP() / 100) * 25)\n    target:addMP((target:getMaxMP() / 100) * 25)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP_AND_MP)\nend\n\nreturn itemObject\n"},["scripts/items/vile_elixir_+1.lua"]={["Path"]="scripts/items/vile_elixir_+1.lua",["SHA256"]="ec293af43b52425bfb850ee812f7c6deefd123a7736f0bd94edca696d6599c35",["Text"]="-----------------------------------\n-- ID: 4175\n-- Item: Vile Elixir +1\n-- Item Effect: Instantly restores 55% of HP and MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    local mHP = target:getMaxHP()\n    local cHP = target:getHP()\n    local mMP = target:getMaxMP()\n    local cMP = target:getMP()\n\n    if mHP == cHP and mMP == cMP then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE -- Does not let player use item if their hp and mp are full\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target)\n    target:addHP((target:getMaxHP() / 100) * 55)\n    target:addMP((target:getMaxMP() / 100) * 55)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP_AND_MP)\nend\n\nreturn itemObject\n"},["scripts/items/virga_cell.lua"]={["Path"]="scripts/items/virga_cell.lua",["SHA256"]="f377b0138931d0ad16f290927cee436784ea7d561956638b32fbd4a2653fe42b",["Text"]="-----------------------------------\n-- Virga Cell\n-- ID 5372\n-- Unlocks earring and ring equipment\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.salvage.onCellItemCheck(target, xi.effect.ENCUMBRANCE_I, 0x7800)\nend\n\nitemObject.onItemUse = function(target)\n    return xi.salvage.onCellItemUse(target, xi.effect.ENCUMBRANCE_I, 0x7800, 7)\nend\n\nreturn itemObject\n"},["scripts/items/virtue_stone_pouch.lua"]={["Path"]="scripts/items/virtue_stone_pouch.lua",["SHA256"]="c92973bf46a715809bbe3634a8bb186f185c32bd7f2fc213e730c42f7da6f640",["Text"]="-----------------------------------\n-- ID: 5410\n-- virtue_stone_pouch.lua\n-- When used, you will obtain one stack of virtue stone\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.VIRTUE_STONE, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/vision_ring.lua"]={["Path"]="scripts/items/vision_ring.lua",["SHA256"]="db0d65edd071a7500a860d8f0221a49a1536618ffe25cc944b1e1c1193e54e75",["Text"]="-----------------------------------\n-- ID: 15559\n-- Item: vision_ring\n-- Item Effect: ACC+2 RACC+2\n-- Duration: 30 Minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.VISION_RING) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.VISION_RING)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.VISION_RING) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 1800, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.VISION_RING })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.ACC, 2)\n    effect:addMod(xi.mod.RACC, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/vitality_potion.lua"]={["Path"]="scripts/items/vitality_potion.lua",["SHA256"]="be72b4aac98b7553b032485f25983e57e85600c712e719efaa104014b6fe5ab8",["Text"]="-----------------------------------\n-- ID: 4203\n-- vitality_potion\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.VIT_BOOST, { power = 7, duration = 180, origin = user })\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 900, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/vocation_ring.lua"]={["Path"]="scripts/items/vocation_ring.lua",["SHA256"]="39e0f5916e2af8cdc39165d95d6f52af0935ef30f3743c8fc124388918e3ebea",["Text"]="-----------------------------------\n-- ID: 28563\n-- Item: vocation ring\n-- Capacity point bonus\n-----------------------------------\n-- Bonus: +100%\n-- Duration: 720 min\n-- Max bonus: 12000 exp\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if target:hasStatusEffect(xi.effect.COMMITMENT) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.COMMITMENT\n    local power     = 100\n    local duration  = 43200\n    local subpower  = 12000\n\n    xi.itemUtils.addItemExpEffect(target, effect, power, duration, subpower)\nend\n\nreturn itemObject\n"},["scripts/items/voidstorm_schema.lua"]={["Path"]="scripts/items/voidstorm_schema.lua",["SHA256"]="ea567ffad00b364ee2890c5d72bee07c4f170cd457f97d4f137fdf13ef4e3445",["Text"]="-----------------------------------\n-- ID: 6056\n-- Voidstorm Schema\n-- Teaches the white magic Voidstorm\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.VOIDSTORM)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.VOIDSTORM)\nend\n\nreturn itemObject\n"},["scripts/items/voluspa_bolt_quiver.lua"]={["Path"]="scripts/items/voluspa_bolt_quiver.lua",["SHA256"]="c986a44bce8bc29b2ef9a898e5838c9f665c5c66d622d988baf67fb8226e578b",["Text"]="-----------------------------------\n-- ID: 6429\n-- Voluspa Volt Quiver\n-- When used, you will obtain one stack of Voluspa Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.VOLUSPA_BOLT, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/voluspa_bullet_pouch.lua"]={["Path"]="scripts/items/voluspa_bullet_pouch.lua",["SHA256"]="51d86fb88f016c5fa526527360e3a0dc2ddb9fb26bb7b0017f1b63510d7dddfb",["Text"]="-----------------------------------\n-- ID: 6438\n-- Voluspa Bullet Pouch\n-- When used, you will obtain one stack of Voluspa Bullets\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.VOLUSPA_BULLET, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/voluspa_quiver.lua"]={["Path"]="scripts/items/voluspa_quiver.lua",["SHA256"]="ce0e3b6083642e8c0fd4bcefe10333d3ad95e73c2ab83049cf3aff92a6470f9b",["Text"]="-----------------------------------\n-- ID: 6420\n-- Voluspa Quiver\n-- When used, you will obtain one stack of Voluspa Arrows\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.VOLUSPA_ARROW, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/vomp_carrot.lua"]={["Path"]="scripts/items/vomp_carrot.lua",["SHA256"]="705baad15113d877ba2e35689be74fcdb31c442712ff652f3d28d94b633a0ed5",["Text"]="-----------------------------------\n-- ID: 5607\n-- vomp_carrot\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 2)\n    effect:addMod(xi.mod.VIT, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/vongola_clam.lua"]={["Path"]="scripts/items/vongola_clam.lua",["SHA256"]="0fd55c8404b240777b1ecbae9e44fc9a386d30421bcbca0e46f24093ae456f9c",["Text"]="-----------------------------------\n-- ID: 5131\n-- Item: Vongola Clam\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity -5\n-- Vitality 4\n-- Defense +17% - 50 Cap\n-- HP 5% - 50 Cap\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, -5)\n    effect:addMod(xi.mod.VIT, 4)\n    effect:addMod(xi.mod.FOOD_DEFP, 17)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 50)\n    effect:addMod(xi.mod.FOOD_HPP, 5)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 50)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/vulcan_blade.lua"]={["Path"]="scripts/items/vulcan_blade.lua",["SHA256"]="5cd316b0a62fff3472c33891a74f6300d9337dfd309e61d70b79c593e83d18a3",["Text"]="-----------------------------------\n-- ID: 17706\n-- Item: Vulcan Blade\n-- Item Effect: Enfire\n-- Duration: 3 minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 7,\n        basePower      = math.randomInt(3, 5),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nitemObject.onItemCheck = function(target, user)\n    if target:getStatusEffectBySource(xi.effect.ENFIRE, xi.effectSourceType.EQUIPPED_ITEM, xi.item.VULCAN_BLADE) ~= nil then\n        target:delStatusEffect(xi.effect.ENFIRE, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.VULCAN_BLADE)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.VULCAN_BLADE) then\n        target:addStatusEffect(xi.effect.ENFIRE, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.VULCAN_BLADE })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    local magicskill = target:getSkillLevel(xi.skill.ENHANCING_MAGIC)\n    local potency = 0\n\n    if magicskill <= 200 then\n        potency = 3 + math.floor(6 * magicskill / 100)\n    elseif magicskill > 200 then\n        potency = 5 + math.floor(5 * magicskill / 100)\n    end\n\n    potency = utils.clamp(potency, 3, 25)\n\n    effect:addMod(xi.mod.ENSPELL, xi.element.FIRE)\n    effect:addMod(xi.mod.ENSPELL_DMG, potency)\n    effect:addMod(xi.mod.ENSPELL_CHANCE, 100)\nend\n\n-- Empty function required for onEffectGain to work\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/vulcan_claymore.lua"]={["Path"]="scripts/items/vulcan_claymore.lua",["SHA256"]="75bee1a729284d30b7832e47bbd28bb9f5b8a1f9baf8194af4fbdb3027ae4faa",["Text"]="-----------------------------------\n-- ID: 18379\n-- Item: Vulcan Claymore\n-- Additional effect: fire damage\n-- Item Effect: Enfire\n-- Duration: 3 minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 10,\n        basePower      = math.randomInt(6, 8),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nitemObject.onItemCheck = function(target, user)\n    if target:getStatusEffectBySource(xi.effect.ENFIRE, xi.effectSourceType.EQUIPPED_ITEM, xi.item.VULCAN_CLAYMORE) ~= nil then\n        target:delStatusEffect(xi.effect.ENFIRE, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.VULCAN_CLAYMORE)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.VULCAN_CLAYMORE) then\n        target:addStatusEffect(xi.effect.ENFIRE, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.VULCAN_CLAYMORE })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    local magicskill = target:getSkillLevel(xi.skill.ENHANCING_MAGIC)\n    local potency = 0\n\n    if magicskill <= 200 then\n        potency = 3 + math.floor(6 * magicskill / 100)\n    elseif magicskill > 200 then\n        potency = 5 + math.floor(5 * magicskill / 100)\n    end\n\n    potency = utils.clamp(potency, 3, 25)\n\n    effect:addMod(xi.mod.ENSPELL, xi.element.FIRE)\n    effect:addMod(xi.mod.ENSPELL_DMG, potency)\n    effect:addMod(xi.mod.ENSPELL_CHANCE, 100)\nend\n\n-- Empty function required for onEffectGain to work\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/vulcan_degen.lua"]={["Path"]="scripts/items/vulcan_degen.lua",["SHA256"]="a73c925d5c1c58c8065a1049cde9354a6e0f8717b0ea2102b9c62f76e7e2281c",["Text"]="-----------------------------------\n-- ID: 17705\n-- Item: Vulcan Degen\n-- Additional effect: fire damage\n-- Item Effect: Enfire\n-- Duration: 3 minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 7,\n        basePower      = math.randomInt(3, 5),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nitemObject.onItemCheck = function(target, user)\n    if target:getStatusEffectBySource(xi.effect.ENFIRE, xi.effectSourceType.EQUIPPED_ITEM, xi.item.VULCAN_DEGEN) ~= nil then\n        target:delStatusEffect(xi.effect.ENFIRE, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.VULCAN_DEGEN)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.VULCAN_DEGEN) then\n        target:addStatusEffect(xi.effect.ENFIRE, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.VULCAN_DEGEN })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    local magicskill = target:getSkillLevel(xi.skill.ENHANCING_MAGIC)\n    local potency = 0\n\n    if magicskill <= 200 then\n        potency = 3 + math.floor(6 * magicskill / 100)\n    elseif magicskill > 200 then\n        potency = 5 + math.floor(5 * magicskill / 100)\n    end\n\n    potency = utils.clamp(potency, 3, 25)\n\n    effect:addMod(xi.mod.ENSPELL, xi.element.FIRE)\n    effect:addMod(xi.mod.ENSPELL_DMG, potency)\n    effect:addMod(xi.mod.ENSPELL_CHANCE, 100)\nend\n\n-- Empty function required for onEffectGain to work\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/vulcan_sword.lua"]={["Path"]="scripts/items/vulcan_sword.lua",["SHA256"]="c1b860019c935f64b9d9f829351267b03c73142836e4b1de202ae31b6a2da501",["Text"]="-----------------------------------\n-- ID: 17704\n-- Item: Vulcan Sword\n-- Additional effect: fire damage\n-- Item Effect: Enfire\n-- Duration: 3 minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 5,\n        basePower      = math.randomInt(3, 5),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nitemObject.onItemCheck = function(target, user)\n    if target:getStatusEffectBySource(xi.effect.ENFIRE, xi.effectSourceType.EQUIPPED_ITEM, xi.item.VULCAN_SWORD) ~= nil then\n        target:delStatusEffect(xi.effect.ENFIRE, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.VULCAN_SWORD)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.VULCAN_SWORD) then\n        target:addStatusEffect(xi.effect.ENFIRE, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.VULCAN_SWORD })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    local magicskill = target:getSkillLevel(xi.skill.ENHANCING_MAGIC)\n    local potency = 0\n\n    if magicskill <= 200 then\n        potency = 3 + math.floor(6 * magicskill / 100)\n    elseif magicskill > 200 then\n        potency = 5 + math.floor(5 * magicskill / 100)\n    end\n\n    potency = utils.clamp(potency, 3, 25)\n\n    effect:addMod(xi.mod.ENSPELL, xi.element.FIRE)\n    effect:addMod(xi.mod.ENSPELL_DMG, potency)\n    effect:addMod(xi.mod.ENSPELL_CHANCE, 100)\nend\n\n-- Empty function required for onEffectGain to work\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/vulcans_staff.lua"]={["Path"]="scripts/items/vulcans_staff.lua",["SHA256"]="6c4ece4276b0c2a96a725e79c3a72f76f4dd78933bb87b3eb9678f0cb64ed220",["Text"]="-----------------------------------\n-- ID: 17546\n-- Item: Vulcan's Staff\n-- Additional effect: fire damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 25, -- guessed\n        basePower      = math.randomInt(25, 34),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/walnut.lua"]={["Path"]="scripts/items/walnut.lua",["SHA256"]="ade51a996bb0ffdf455b5b0d82001fdac436a77ade6fbd97ec3ac2e51238bf34",["Text"]="-----------------------------------\n-- ID: 5661\n-- Item: Walnut\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- HP 30\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 30)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/walnut_cookie.lua"]={["Path"]="scripts/items/walnut_cookie.lua",["SHA256"]="77d75576fa300b4337651c3117ed9236bdaac19a87fe8447265351ed18c94fc2",["Text"]="-----------------------------------\n-- ID: 5922\n-- Item: Walnut Cookie\n-- Food Effect: 3 Min, All Races\n-----------------------------------\n-- HP Healing 3\n-- MP Healing 6\n-- Bird Killer 10\n-- Resist Paralyze 10\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 180, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.HPHEAL, 3)\n    effect:addMod(xi.mod.MPHEAL, 6)\n    effect:addMod(xi.mod.BIRD_KILLER, 10)\n    effect:addMod(xi.mod.PARALYZERES, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/walrus_staff.lua"]={["Path"]="scripts/items/walrus_staff.lua",["SHA256"]="f0d01e05d9b909a33b233e0c2ac4ab3eb5114d172f854186e8718932a2030756",["Text"]="-----------------------------------\n-- ID: 17135\n-- Item: Walrus Staff\n-- Additional effect: ice damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = 8 + utils.clamp(dStat * 3 / 27, 0, 25), -- 0-8% over 54 dINT, approx.\n        basePower      = math.randomInt(12, 16),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.ICE,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/warm_egg.lua"]={["Path"]="scripts/items/warm_egg.lua",["SHA256"]="e0d88d78763c356870b094f007144ccf2f208fa91aedd9759e1969da0e34fde5",["Text"]="-----------------------------------\n-- ID: 4602\n-- Item: warm_egg\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Health 18\n-- Magic 18\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 18)\n    effect:addMod(xi.mod.FOOD_MP, 18)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/warp_cudgel.lua"]={["Path"]="scripts/items/warp_cudgel.lua",["SHA256"]="2c8346167d4d94e4df8d6758764bd9a17e90a6d150eee83909b2dc0422939b9a",["Text"]="-----------------------------------\n-- ID: 17040\n-- Warp Cudgel\n-- Transports the user to their Home Point\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.WARP, duration = 3, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/warp_ring.lua"]={["Path"]="scripts/items/warp_ring.lua",["SHA256"]="b3a3d0ccab0cde833477598ffac9d0f2bf89700dfaecc9ee33fea9490c7ea230",["Text"]="-----------------------------------\n-- ID: 28540\n-- Warp Ring\n--  Transports the user to their Home Point\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.WARP, duration = 3, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/warrior_die.lua"]={["Path"]="scripts/items/warrior_die.lua",["SHA256"]="7103a16f1c05457d07ad4cdc8b1b0953e21bd93b8423963afe76d0734fbd527e",["Text"]="-----------------------------------\n-- ID: 5477\n-- Warrior Die\n-- Teaches the job ability Fighter's Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.FIGHTERS_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.FIGHTERS_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/water_arrow.lua"]={["Path"]="scripts/items/water_arrow.lua",["SHA256"]="2357cfd422fa280ba56d4c73a93c3a6d3a805df7a775103345bf55aa9d6a14e7",["Text"]="-----------------------------------\n-- ID: 18698\n-- Item: Water Arrow\n-- Additional effect: Water damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    -- Unconfirmed power.\n\n    local pTable =\n    {\n        ignoreEnSpell   = true,\n        basePower       = 10 + utils.clamp(dStat, -3, 8) + utils.clamp(math.floor((dStat - 8) / 2), 0, 8),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.WATER,\n        canResist       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/water_card_case.lua"]={["Path"]="scripts/items/water_card_case.lua",["SHA256"]="da2c53b56205fa8f5b7aa3570a9ea93a2b16e38c1cb5243b944f983eb7ef8a28",["Text"]="-----------------------------------\n-- ID: 5407\n-- Water Card Case\n-- When used, you will obtain one stack of Water Cards\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.WATER_CARD, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/water_cluster.lua"]={["Path"]="scripts/items/water_cluster.lua",["SHA256"]="020d68175a7fd15501d118a7032ca122047a6a0930b196e17baec2bedeb94cbc",["Text"]="-----------------------------------\n-- ID: 4109\n-- Water Cluster\n-- Turn into a stack of water crystals\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.WATER_CRYSTAL, 12 } })\nend\n\nreturn itemObject\n"},["scripts/items/water_mitts.lua"]={["Path"]="scripts/items/water_mitts.lua",["SHA256"]="80920d8e6495c04cda217f519fb1b57e58b978eed32dd53be549187d23dbf905",["Text"]="-----------------------------------\n-- ID: 14992\n-- Water Mitts\n--  Enchantment: \"Enwater\"\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local fakeSpell = GetSpell(xi.magic.spell.ENWATER)\n    xi.spells.enhancing.useEnhancingSpell(target, target, fakeSpell)\nend\n\nreturn itemObject\n"}};
